import React, { useState } from 'react';
import axios from 'axios';
import { toast } from 'react-toastify';
import { login, signup } from '../services/api';
import './Login.css';

function Login({ onLoginSuccess }) {
  const [isDev, setIsDev] = useState(false);
  const [email, setEmail] = useState('farmer@agri.coop');
  const [password, setPassword] = useState('password123');
  const [rememberMe, setRememberMe] = useState(true);
  const [showPassword, setShowPassword] = useState(false);
  const [loading, setLoading] = useState(false);

  // Accurate Location state for Farmer side
  const [isLocating, setIsLocating] = useState(false);
  const [locationMeta, setLocationMeta] = useState(null);

  // Sign up modal state
  const [signupForm, setSignupForm] = useState({
    name: '',
    age: 28,
    email: '',
    password: '',
    role: 'farmer',
    farmName: '',
    farmLocation: '',
    organization: ''
  });

  const handleDetectLocation = () => {
    if (!navigator.geolocation) {
      toast.error('Geolocation is not supported by your browser.');
      return;
    }

    setIsLocating(true);
    toast.info('📍 Acquiring high-accuracy GPS coordinates from device...');

    navigator.geolocation.getCurrentPosition(
      async (pos) => {
        const { latitude, longitude, accuracy } = pos.coords;
        const latFixed = latitude.toFixed(4);
        const lonFixed = longitude.toFixed(4);
        let resolvedLocation = `GPS (${latFixed}°, ${lonFixed}°)`;

        try {
          const res = await axios.get(
            `https://nominatim.openstreetmap.org/reverse?format=jsonv2&lat=${latitude}&lon=${longitude}`,
            { timeout: 7000 }
          );
          if (res.data && res.data.address) {
            const addr = res.data.address;
            const locality = addr.city || addr.town || addr.municipality || addr.village || addr.suburb || '';
            const province = addr.state || addr.region || addr.county || '';
            const country = addr.country || '';
            const parts = [locality, province, country].filter(Boolean);
            if (parts.length > 0) {
              resolvedLocation = `${parts.join(', ')} (${latFixed}°, ${lonFixed}°)`;
            } else if (res.data.display_name) {
              resolvedLocation = `${res.data.display_name.split(',').slice(0, 3).join(',')} (${latFixed}°, ${lonFixed}°)`;
            }
          }
        } catch (e) {
          console.warn('Reverse geocoding network error (using raw coordinates):', e);
        }

        setSignupForm(prev => ({
          ...prev,
          farmLocation: resolvedLocation
        }));

        setLocationMeta({
          latitude: latFixed,
          longitude: lonFixed,
          accuracy: Math.round(accuracy),
          formatted: resolvedLocation
        });

        toast.success(`📍 Accurate location acquired! (±${Math.round(accuracy)}m)`);
        setIsLocating(false);
      },
      (err) => {
        console.warn('Geolocation error:', err);
        let msg = 'Could not acquire GPS position.';
        if (err.code === 1) msg = 'Location permission was denied. Please allow location access or select/type manually.';
        else if (err.code === 2) msg = 'GPS signal unavailable. Please select or type your location manually.';
        else if (err.code === 3) msg = 'Location request timed out. Please try again or select manually.';
        toast.warn(msg);
        setIsLocating(false);
      },
      { enableHighAccuracy: true, timeout: 12000, maximumAge: 0 }
    );
  };

  const handleSelectPresetLocation = (preset) => {
    setSignupForm(prev => ({ ...prev, farmLocation: preset }));
    setLocationMeta(null);
    toast.info(`Selected location: ${preset}`);
  };

  const toggleMode = (targetIsDev) => {
    setIsDev(targetIsDev);
    if (targetIsDev) {
      if (email === 'farmer@agri.coop') setEmail('dev@agri.coop');
    } else {
      if (email === 'dev@agri.coop') setEmail('farmer@agri.coop');
    }
  };

  const handleQuickFill = (role) => {
    if (role === 'farmer') {
      setIsDev(false);
      setEmail('farmer@agri.coop');
      setPassword('password123');
      toast.info('Loaded Farmer demo credentials.');
    } else {
      setIsDev(true);
      setEmail('dev@agri.coop');
      setPassword('password123');
      toast.info('Loaded Dev & Research demo credentials.');
    }
  };

  const handleLoginSubmit = async (e) => {
    e.preventDefault();
    if (!email || !password) {
      toast.warn('Please enter both email and password.');
      return;
    }

    setLoading(true);
    const role = isDev ? 'dev' : 'farmer';

    try {
      // Call backend API
      const res = await login(email, password, role);
      if (res.success && res.user) {
        toast.success(res.message || `Welcome, ${res.user.name}!`);
        if (onLoginSuccess) {
          onLoginSuccess(res.user);
        }
      } else {
        toast.error(res.error || 'Authentication failed.');
      }
    } catch (err) {
      console.warn('Backend login fallback:', err);
      // Fallback demo authentication if backend is unreachable
      const cleanEmail = email.trim().toLowerCase();
      if (cleanEmail === 'farmer@agri.coop' || !isDev) {
        const fallbackUser = {
          name: cleanEmail === 'farmer@agri.coop' ? 'John Miller' : cleanEmail.split('@')[0],
          email: cleanEmail,
          role: 'farmer',
          profile: { farmName: 'Green Valley Organic Farms' }
        };
        toast.success(`Welcome, ${fallbackUser.name}! (Farmer Mode)`);
        if (onLoginSuccess) onLoginSuccess(fallbackUser);
      } else {
        const fallbackUser = {
          name: cleanEmail === 'dev@agri.coop' ? 'Alex Chen' : cleanEmail.split('@')[0],
          email: cleanEmail,
          role: 'dev',
          profile: { organization: 'AgriTech AI Labs' }
        };
        toast.success(`Welcome, ${fallbackUser.name}! (Dev & Research Mode)`);
        if (onLoginSuccess) onLoginSuccess(fallbackUser);
      }
    } finally {
      setLoading(false);
    }
  };

  const handleSignupSubmit = async (e) => {
    e.preventDefault();
    if (!signupForm.name || !signupForm.email || !signupForm.password) {
      toast.warn('Please fill in all required fields.');
      return;
    }

    setLoading(true);
    try {
      const res = await signup(signupForm);
      if (res.success && res.user) {
        toast.success(`Profile created! Welcome, ${res.user.name}.`);
        setShowSignupModal(false);
        if (onLoginSuccess) {
          onLoginSuccess(res.user);
        }
      } else {
        toast.error(res.error || 'Registration failed.');
      }
    } catch (err) {
      console.error('Signup error:', err);
      const errMsg = err.response?.data?.error || err.message || 'Signup failed';
      toast.error(errMsg);
    } finally {
      setLoading(false);
    }
  };

  return (
    <div className={`login-page-container ${isDev ? 'theme-dev' : 'theme-farmer'}`}>
      <div className="login-card">
        {/* Header with Title and Mode Badge */}
        <div className="login-header">
          <div className="header-top">
            <div className="header-brand">
              <div className="header-icon-slot">
                {isDev ? '💻' : '🌾'}
              </div>
              <div>
                <h1>ClimaYield-X</h1>
                <p className="header-subtitle">
                  A Data-Driven SARIMA–LSTM Hybrid Model for Predicting Yield Instability in Short-Cycle Vegetables
                </p>
              </div>
            </div>
            <span className="account-badge">
              {isDev ? 'Dev / Researcher Portal' : 'Farmer Portal'}
            </span>
          </div>
        </div>

        {/* Farmer vs Dev Side Interactive Switch */}
        <div className="switch-wrapper">
          <span 
            className={`switch-label ${!isDev ? 'active-farm' : ''}`}
            onClick={() => toggleMode(false)}
          >
            🌾 FarmerSide
          </span>

          <div 
            className={`toggle-track ${isDev ? 'is-dev' : ''}`}
            onClick={() => toggleMode(!isDev)}
            title="Toggle between Farmer and Dev login modes"
          >
            <div className="toggle-knob">
              {isDev ? '💻' : '🌾'}
            </div>
          </div>

          <span 
            className={`switch-label ${isDev ? 'active-dev' : ''}`}
            onClick={() => toggleMode(true)}
          >
            💻 DevSide
          </span>
        </div>

        {/* Active Panel Form */}
        <div className="panel">
          <div className="panel-title">
            <span>{isDev ? '💻 Dev & Pipeline Access' : '🌾 Field Operations & Weather Access'}</span>
          </div>
          <div className="panel-sub">
            {isDev 
              ? 'Hyperparameter tuning, residual learning analysis, and model retraining controls.'
              : 'Local field forecasting, rainfall alerts, irrigation timing, and crop yield projections.'}
          </div>

          {/* 1-Click Quick Fill Helper */}
          <div className="quick-fill-row">
            <button 
              type="button" 
              className="btn-quick-fill"
              onClick={() => handleQuickFill('farmer')}
            >
              ⚡ Fill Farmer Demo
            </button>
            <button 
              type="button" 
              className="btn-quick-fill"
              onClick={() => handleQuickFill('dev')}
            >
              ⚡ Fill Dev Demo
            </button>
          </div>

          <form onSubmit={handleLoginSubmit}>
            {/* Email Field */}
            <div className="login-input-group">
              <label>{isDev ? 'Engineering ID / Email' : 'Farm ID / Email Address'}</label>
              <div className="login-input-wrapper">
                <span className="login-input-icon">{isDev ? '📧' : '🧑‍🌾'}</span>
                <input
                  type="email"
                  value={email}
                  onChange={(e) => setEmail(e.target.value)}
                  placeholder={isDev ? 'dev@agri.coop' : 'farmer@agri.coop'}
                  required
                />
              </div>
            </div>

            {/* Password Field */}
            <div className="login-input-group">
              <label>Password</label>
              <div className="login-input-wrapper">
                <span className="login-input-icon">🔒</span>
                <input
                  type={showPassword ? 'text' : 'password'}
                  value={password}
                  onChange={(e) => setPassword(e.target.value)}
                  placeholder="••••••••"
                  required
                />
                <button
                  type="button"
                  onClick={() => setShowPassword(!showPassword)}
                  style={{ background: 'none', border: 'none', cursor: 'pointer', opacity: 0.6, fontSize: '0.9rem' }}
                >
                  {showPassword ? '👁️' : '🙈'}
                </button>
              </div>
            </div>

            {/* Remember Me & Forgot Password */}
            <div className="login-options-row">
              <label className="remember-label">
                <input
                  type="checkbox"
                  checked={rememberMe}
                  onChange={(e) => setRememberMe(e.target.checked)}
                />
                Remember this terminal
              </label>
              <span 
                className="forgot-link"
                onClick={() => toast.info('Default demo password is: password123')}
              >
                Forgot password?
              </span>
            </div>

            {/* Submit Button */}
            <button 
              type="submit" 
              className="btn-auth-submit"
              disabled={loading}
            >
              {loading 
                ? '⏳ Verifying Credentials...' 
                : isDev 
                  ? '💻 Enter Dev & Research Suite' 
                  : '🌾 Enter Field Dashboard'}
            </button>
          </form>

          {/* Signup Trigger */}
          <div className="auth-switch-prompt">
            Don't have an account yet?{' '}
            <button 
              type="button"
              className="auth-switch-btn"
              onClick={() => {
                setSignupForm(prev => ({ ...prev, role: isDev ? 'dev' : 'farmer' }));
                setShowSignupModal(true);
              }}
            >
              Create {isDev ? 'Dev Profile' : 'Farm Profile'}
            </button>
          </div>
        </div>
      </div>

      {/* Signup Modal */}
      {showSignupModal && (
        <div className="auth-modal-overlay" onClick={() => setShowSignupModal(false)}>
          <div className="auth-modal-card" onClick={(e) => e.stopPropagation()}>
            <div style={{ display: 'flex', justifyContent: 'space-between', alignItems: 'center', marginBottom: '15px' }}>
              <h3 style={{ margin: 0, color: '#2c3e50' }}>
                {signupForm.role === 'dev' ? '💻 Create Dev & Research Account' : '🌾 Register New Farm Profile'}
              </h3>
              <button 
                onClick={() => setShowSignupModal(false)}
                style={{ background: 'none', border: 'none', fontSize: '1.2rem', cursor: 'pointer' }}
              >
                ✖
              </button>
            </div>

            <form onSubmit={handleSignupSubmit}>
              <div className="login-input-group">
                <label>Full Name</label>
                <div className="login-input-wrapper">
                  <input
                    type="text"
                    value={signupForm.name}
                    onChange={(e) => setSignupForm({ ...signupForm, name: e.target.value })}
                    placeholder={signupForm.role === 'dev' ? 'Alex Chen' : 'John Miller'}
                    required
                  />
                </div>
              </div>

              <div className="login-input-group">
                <label>Age</label>
                <div className="login-input-wrapper">
                  <input
                    type="number"
                    min="18"
                    max="99"
                    value={signupForm.age}
                    onChange={(e) => setSignupForm({ ...signupForm, age: e.target.value })}
                    placeholder="e.g. 30"
                    required
                  />
                </div>
              </div>

              <div className="login-input-group">
                <label>Email Address</label>
                <div className="login-input-wrapper">
                  <input
                    type="email"
                    value={signupForm.email}
                    onChange={(e) => setSignupForm({ ...signupForm, email: e.target.value })}
                    placeholder="user@organization.com"
                    required
                  />
                </div>
              </div>

              <div className="login-input-group">
                <label>Password</label>
                <div className="login-input-wrapper">
                  <input
                    type="password"
                    value={signupForm.password}
                    onChange={(e) => setSignupForm({ ...signupForm, password: e.target.value })}
                    placeholder="Create a secure password"
                    required
                  />
                </div>
              </div>

              {signupForm.role === 'farmer' && (
                <>
                  <div className="login-input-group">
                    <label>Farm Name</label>
                    <div className="login-input-wrapper">
                      <span className="login-input-icon">🏡</span>
                      <input
                        type="text"
                        value={signupForm.farmName}
                        onChange={(e) => setSignupForm({ ...signupForm, farmName: e.target.value })}
                        placeholder="e.g. Green Valley Organic Farm"
                      />
                    </div>
                  </div>

                  <div className="login-input-group">
                    <div style={{ display: 'flex', justifyContent: 'space-between', alignItems: 'center', marginBottom: '6px' }}>
                      <label style={{ margin: 0 }}>Accurate Farm Location</label>
                      <button
                        type="button"
                        onClick={handleDetectLocation}
                        disabled={isLocating}
                        className="btn-gps-detect"
                      >
                        {isLocating ? '⏳ Locating...' : '📍 Detect GPS Location'}
                      </button>
                    </div>
                    <div className="login-input-wrapper">
                      <span className="login-input-icon">📍</span>
                      <input
                        type="text"
                        value={signupForm.farmLocation}
                        onChange={(e) => {
                          setSignupForm({ ...signupForm, farmLocation: e.target.value });
                          setLocationMeta(null);
                        }}
                        placeholder="e.g. La Trinidad, Benguet, Philippines"
                        required
                      />
                    </div>

                    {locationMeta && (
                      <div className="gps-accuracy-badge">
                        <span>🎯 GPS Verified: ±{locationMeta.accuracy}m</span>
                        <span>•</span>
                        <span>Lat {locationMeta.latitude}° · Lon {locationMeta.longitude}°</span>
                      </div>
                    )}

                    <div className="location-presets">
                      <span className="presets-label">Agricultural Regions:</span>
                      {['Benguet', 'Bukidnon', 'Laguna', 'Quezon', 'Nueva Ecija'].map((region) => (
                        <button
                          key={region}
                          type="button"
                          className="preset-chip"
                          onClick={() => handleSelectPresetLocation(`${region}, Philippines`)}
                        >
                          {region}
                        </button>
                      ))}
                    </div>
                  </div>
                </>
              )}

              <div style={{ display: 'flex', gap: '10px', marginTop: '20px' }}>
                <button 
                  type="button" 
                  className="btn-secondary" 
                  style={{ flex: 1 }}
                  onClick={() => setShowSignupModal(false)}
                >
                  Cancel
                </button>
                <button 
                  type="submit" 
                  className="btn-auth-submit" 
                  style={{ flex: 2 }}
                  disabled={loading}
                >
                  {loading ? 'Creating...' : 'Register & Enter'}
                </button>
              </div>
            </form>
          </div>
        </div>
      )}
    </div>
  );
}

export default Login;
